import React from "react";
import { render, fireEvent } from "@testing-library/react-native";
import Header from "../Header";

// Mock the CoinsDisplay component
jest.mock("../CoinsDisplay", () => {
  const React = require("react");
  const { View, Text, TouchableOpacity } = require("react-native");

  const MockCoinsDisplay = ({
    coins,
    onPress,
  }: {
    coins: number;
    onPress?: () => void;
  }) => {
    if (onPress) {
      return (
        <TouchableOpacity testID="coins-display-touchable" onPress={onPress}>
          <View testID="coins-display">
            <Text>{coins}</Text>
          </View>
        </TouchableOpacity>
      );
    }
    return (
      <View testID="coins-display">
        <Text>{coins}</Text>
      </View>
    );
  };

  MockCoinsDisplay.displayName = "MockCoinsDisplay";
  return MockCoinsDisplay;
});

// Mock the HintIcon component
jest.mock("../icons/HintIcon", () => {
  const React = require("react");
  const { View } = require("react-native");

  const MockHintIcon = ({
    width,
    height,
    color,
  }: {
    width: number;
    height: number;
    color: string;
  }) => (
    <View
      testID="hint-icon"
      style={{ width, height, backgroundColor: color }}
    />
  );

  MockHintIcon.displayName = "MockHintIcon";
  return MockHintIcon;
});

// Mock AppStrings
jest.mock("../../constants/AppStrings", () => ({
  AppStrings: {
    Navigation: {
      HINT_BUTTON: "Hint",
    },
  },
}));

describe("Header", () => {
  const defaultProps = {
    userCoins: 100,
    onHintPress: jest.fn(),
    onCoinsPress: jest.fn(),
  };

  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe("Rendering", () => {
    it("renders correctly with all elements", () => {
      const { getByText, getByTestId } = render(<Header {...defaultProps} />);

      expect(getByText("Hint")).toBeTruthy();
      expect(getByText("100")).toBeTruthy();
      expect(getByTestId("hint-icon")).toBeTruthy();
      expect(getByTestId("coins-display")).toBeTruthy();
    });

    it("renders with zero coins", () => {
      const { getByText } = render(<Header {...defaultProps} userCoins={0} />);

      expect(getByText("0")).toBeTruthy();
    });

    it("renders with large coin amounts", () => {
      const { getByText } = render(
        <Header {...defaultProps} userCoins={999999} />
      );

      expect(getByText("999999")).toBeTruthy();
    });

    it("has proper layout structure", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const header = getByTestId("header");
      expect(header.props.style).toMatchObject({
        width: "100%",
        flexDirection: "row",
        alignItems: "center",
        justifyContent: "space-between",
        padding: 16,
        backgroundColor: "#e5e7eb", // bg-gray-200
      });
    });

    it("has proper left side layout", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const leftSide = getByTestId("header-left-side");
      expect(leftSide.props.style).toMatchObject({
        flexDirection: "row",
        alignItems: "center",
      });
    });
  });

  describe("Hint Button", () => {
    it("renders hint button with correct text", () => {
      const { getByText } = render(<Header {...defaultProps} />);

      expect(getByText("Hint")).toBeTruthy();
    });

    it("renders hint icon with correct props", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const hintIcon = getByTestId("hint-icon");
      expect(hintIcon.props.style).toMatchObject({
        width: 24,
        height: 24,
        backgroundColor: "#222",
      });
    });

    it("calls onHintPress when hint button is pressed", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const hintButton = getByTestId("hint-button");
      fireEvent.press(hintButton);

      expect(defaultProps.onHintPress).toHaveBeenCalledTimes(1);
    });

    it("calls onHintPress multiple times when pressed multiple times", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const hintButton = getByTestId("hint-button");
      fireEvent.press(hintButton);
      fireEvent.press(hintButton);
      fireEvent.press(hintButton);

      expect(defaultProps.onHintPress).toHaveBeenCalledTimes(3);
    });

    it("has proper accessibility properties", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const hintButton = getByTestId("hint-button");
      expect(hintButton.props.accessible).toBeTruthy();
      expect(hintButton.props.accessibilityRole).toBe("button");
      expect(hintButton.props.accessibilityLabel).toBe(
        "Get hint for current riddle"
      );
    });
  });

  describe("Coins Display", () => {
    it("passes correct coins amount to CoinsDisplay", () => {
      const { getByText } = render(
        <Header {...defaultProps} userCoins={250} />
      );

      expect(getByText("250")).toBeTruthy();
    });

    it("passes onCoinsPress to CoinsDisplay", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const coinsDisplay = getByTestId("coins-display-touchable");
      fireEvent.press(coinsDisplay);

      expect(defaultProps.onCoinsPress).toHaveBeenCalledTimes(1);
    });

    it("calls onCoinsPress multiple times when pressed multiple times", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const coinsDisplay = getByTestId("coins-display-touchable");
      fireEvent.press(coinsDisplay);
      fireEvent.press(coinsDisplay);

      expect(defaultProps.onCoinsPress).toHaveBeenCalledTimes(2);
    });
  });

  describe("Component Integration", () => {
    it("renders both hint button and coins display in left side", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const leftSide = getByTestId("header-left-side");
      const hintButton = getByTestId("hint-button");
      const coinsDisplay = getByTestId("coins-display");

      expect(leftSide).toBeTruthy();
      expect(hintButton).toBeTruthy();
      expect(coinsDisplay).toBeTruthy();
    });

    it("maintains proper spacing between elements", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const leftSide = getByTestId("header-left-side");
      expect(leftSide.props.className).toContain("space-x-3");
    });

    it("has empty right side for future expansion", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const rightSide = getByTestId("header-right-side");
      expect(rightSide).toBeTruthy();
      expect(rightSide.children).toHaveLength(0);
    });
  });

  describe("Props Handling", () => {
    it("handles different coin amounts correctly", () => {
      const { getByText, rerender } = render(
        <Header {...defaultProps} userCoins={50} />
      );

      expect(getByText("50")).toBeTruthy();

      rerender(<Header {...defaultProps} userCoins={150} />);
      expect(getByText("150")).toBeTruthy();
    });

    it("handles different callback functions correctly", () => {
      const newOnHintPress = jest.fn();
      const newOnCoinsPress = jest.fn();

      const { getByTestId, rerender } = render(<Header {...defaultProps} />);

      // Test original callbacks
      fireEvent.press(getByTestId("hint-button"));
      fireEvent.press(getByTestId("coins-display-touchable"));

      expect(defaultProps.onHintPress).toHaveBeenCalledTimes(1);
      expect(defaultProps.onCoinsPress).toHaveBeenCalledTimes(1);

      // Test new callbacks
      rerender(
        <Header
          userCoins={100}
          onHintPress={newOnHintPress}
          onCoinsPress={newOnCoinsPress}
        />
      );

      fireEvent.press(getByTestId("hint-button"));
      fireEvent.press(getByTestId("coins-display-touchable"));

      expect(newOnHintPress).toHaveBeenCalledTimes(1);
      expect(newOnCoinsPress).toHaveBeenCalledTimes(1);
      expect(defaultProps.onHintPress).toHaveBeenCalledTimes(1); // Should not be called again
      expect(defaultProps.onCoinsPress).toHaveBeenCalledTimes(1); // Should not be called again
    });
  });

  describe("Edge Cases", () => {
    it("handles negative coin amounts", () => {
      const { getByText } = render(
        <Header {...defaultProps} userCoins={-50} />
      );

      expect(getByText("-50")).toBeTruthy();
    });

    it("handles decimal coin amounts", () => {
      const { getByText } = render(
        <Header {...defaultProps} userCoins={123.45} />
      );

      expect(getByText("123.45")).toBeTruthy();
    });

    it("handles very large coin amounts", () => {
      const { getByText } = render(
        <Header {...defaultProps} userCoins={Number.MAX_SAFE_INTEGER} />
      );

      expect(getByText(Number.MAX_SAFE_INTEGER.toString())).toBeTruthy();
    });

    it("does not crash when callbacks are undefined", () => {
      const { getByTestId } = render(
        <Header
          userCoins={100}
          onHintPress={undefined as any}
          onCoinsPress={undefined as any}
        />
      );

      expect(() => {
        fireEvent.press(getByTestId("hint-button"));
        fireEvent.press(getByTestId("coins-display-touchable"));
      }).not.toThrow();
    });
  });

  describe("Accessibility", () => {
    it("has proper header accessibility", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const header = getByTestId("header");
      expect(header.props.accessible).toBeTruthy();
      expect(header.props.accessibilityRole).toBe("banner");
      expect(header.props.accessibilityLabel).toBe(
        "Game header with hint button and coin balance"
      );
    });

    it("supports screen readers", () => {
      const { getByTestId } = render(<Header {...defaultProps} />);

      const hintButton = getByTestId("hint-button");
      const header = getByTestId("header");

      expect(hintButton.props.accessibilityLabel).toBeTruthy();
      expect(header.props.accessibilityLabel).toBeTruthy();
    });
  });
});
